style.css:
@-moz-document domain("google.com") {
/* Main sidebars & panels */
    div[role="complementary"],
    .aGk, .aj9, .akc, .gbm,
    aside, [class*="sidebar"], [class*="Sidebar"] {
        background-color: rgba(255, 245, 246, 0.85) !important;
        border-color: rgba(255, 164, 182, 0.25) !important;
    }

    /* Google custom buttons and active pill shapes */
    button, 
  VfPpkd-LgbsSe,
    [role="button"],
    [class*="button"]
    [class*="Button"] {
        background-color: #ffc2b4 !important;
        color: #635353 !important;
        border-color: rgba(255, 164, 182, 0.3) !important;
    }

    /* Active icons & navigation states */
    .aZ6, .a3I, .cj, 
    [aria-selected="true"],
    [class*="active"] {
        background-color: rgba(255, 164, 182, 0.2) !important;
        color: #ffa4b6 !important;
    }

    /* Google Tasks interactive checkboxes and text rows */
    .E7Gvyb, .K96Scc, .v96Scc,
    div[role="checkbox"],
    input[type="checkbox"] {
        border-color: #ffc2b4 !important;
    }
    
    div[role="checkbox"][aria-checked="true"] {
        background-color: #ffc2b4 !important;
    }
}
